 "content": "def transform(grid):
    out = [row[:] for row in grid]
    n, m = len(grid), len(grid[0])
    # Each solid 3x3 monochrome block projects its center row and column.
    bars = []
    for r in range(n - 2):
        for c in range(m - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3) for cc in range(c, c + 3)):
                bars.append((color, r + 1, c + 1))
    for color, r, c in bars:
        for j in range(m):
            if out[r][j] == 0:
                out[r][j] = color
        for i in range(n):
            if out[i][c] == 0:
                out[i][c] = color
    # Where projections of different colors cross, leave the crossing blank.
    for a in range(len(bars)):
        ca, ra, xa = bars[a]
        for b in range(a + 1, len(bars)):
            cb, rb, xb = bars[b]
            if ca != cb:
                out[ra][xb] = 0
                out[rb][xa] = 0
    return out
